 void add(String url,String tool){String method=tool.substring(tool.lastIndexOf(' ')+1);if(!method.matches("GET|HEAD|OPTIONS|POST|PUT|PATCH|DELETE"))method="";Item item=items.get(url);if(item==null){if(items.size()>=PassiveUrls.LIMIT)return;item=new Item(++sequence,url);items.put(url,item);item.sources.add(tool);if(!method.isEmpty())item.methods.add(method);model.addRow(new Object[]{item.no,url,tool,item.state,ReconMetadata.category(url),String.join(", ",ReconMetadata.parameters(url)),ReconMetadata.risk(url),ReconMetadata.pattern(url),previous.contains(url)?"이전":"신규",item.methodSummary()});discovery.accept(url,tool);}else{item.last=java.time.Instant.now().toString();if(!method.isEmpty())item.methods.add(method);if(item.sources.add(tool)){refresh(item);discovery.accept(url,tool);}}applyFilter();}
